effect.shader:
void main(){
vec2 uv=acScreenNorm,p=uv-0.5; vec2 dir=vec2(cos(direction),sin(direction));
float t=dot(p,dir)+0.5, f=fract(t*folds), tri=1.0-abs(f*2.0-1.0);
float side=step(0.5,f)*2.0-1.0, z=tri*depth;
vec2 q=p-dir*(side*z*perspective/max(folds,1.0))+0.5;
float valid=step(0.0,q.x)*step(q.x,1.0)*step(0.0,q.y)*step(q.y,1.0);
vec4 src=texture2DCv(inputImg.texture,uv),dst=texture2DCv(inputImg.texture,clamp(q,0.0,1.0));
float light=clamp(0.72+side*depth*0.32,0.3,1.25);
float line=pow(1.0-tri,18.0)*crease;
dst.rgb=dst.rgb*light+line;
gl_FragColor=mix(src,dst,mixAmount*valid);
}
